import { EngagementSignals, FormulaName } from "./types";

/**
 * This file is deliberately structured as a small framework for testing
 * MULTIPLE candidate scoring formulas side by side, rather than hardcoding
 * one calculation -- the team expects to keep tuning this as they learn
 * what actually predicts retention.
 */
type FormulaFn = (signals: EngagementSignals) => number;

/**
 * v1: the original weighting. Schedule edits are treated as the strongest
 * signal (a user editing their schedule is a user planning to register),
 * logins count at face value, and searches are a weak signal since they're
 * cheap and noisy (e.g. accidental navigation).
 *
 * score = 1.0*logins + 3.0*scheduleEdits + 0.5*searches
 */
export const weightedV1: FormulaFn = (s) =>
  s.logins * 1.0 + s.scheduleEdits * 3.0 + s.searches * 0.5;

/**
 * v2: reweighted after the team noticed searches correlated better with
 * next-semester retention than raw login counts, and that a small number
 * of "power users" making dozens of schedule edits were skewing the
 * distribution. Login weight is reduced, search weight is increased, and
 * scheduleEdits is capped at 5 before being weighted so extreme edit counts
 * don't dominate.
 *
 * score = 0.5*logins + 2.0*searches + 2.0*min(scheduleEdits, 5)
 */
export const weightedV2: FormulaFn = (s) =>
  s.logins * 0.5 + s.searches * 2.0 + Math.min(s.scheduleEdits, 5) * 2.0;

export const FORMULA_MAP: Record<FormulaName, FormulaFn> = {
  weightedV1,
  weightedV2,
};
